import React, { useState, useEffect, useContext } from 'react';
import { StaffRolesContext } from '../StaffRolesContext'; // Adjust path if needed

// --- Helper Components ---
const InfoIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor" viewBox="0 0 16 16" style={{ marginLeft: '8px', color: '#6c757d', cursor: 'pointer' }}>
        <path d="M8 15A7 7 0 1 1 8 1a7 7 0 0 1 0 14zm0 1A8 8 0 1 0 8 0a8 8 0 0 0 0 16z"/>
        <path d="m8.93 6.588-2.29.287-.082.38.45.083c.294.055.491.206.552.372.062.166.062.333.062.63v.077c0 .504-.208.927-.62 1.168-.205.122-.47.185-.82.185-.62 0-1.11-.289-1.38-.63-.269-.34-.336-.752-.336-1.195 0-.745.504-1.23 1.22-1.23.635 0 .99.346 1.154.642.165.298.236.648.236.963v.052c0 .285-.05.52-.148.708-.127.248-.306.456-.55.588-.244.132-.527.2-.84.2-.535 0-.938-.202-1.22-.55-.282-.348-.423-.818-.423-1.388 0-.61.22-1.125.66-1.511.44-.386 1.02-.58 1.73-.58.61 0 1.14.164 1.56.49.419.327.67.754.74 1.248.07.493-.046.862-.215 1.123-.17.26-.45.45-.82.563-.37.113-.7.168-1.005.168-.21 0-.39-.03-.53-.09-.14-.06-.25-.13-.33-.22-.08-.09-.13-.2-.16-.33-.03-.13-.04-.28-.04-.46v-.05c0-.28.06-.51.18-.68.12-.17.3-.28.53-.33l.23-.05.28-.24c.25-.21.43-.49.53-.84.1-.35.12-.73.06-1.13-.06-.4-.18-.74-.36-1.02-.18-.28-.43-.5-.73-.66-.3-.16-.66-.24-1.08-.24-.6 0-1.12.18-1.52.53-.4.35-.64.82-.72 1.39-.08.57.02 1.05.28 1.45.26.4.64.7 1.12.85.48.15.98.23 1.5.23.83 0 1.5-.23 1.98-.69.48-.46.72-1.05.72-1.76 0-.6-.17-1.11-.5-1.52-.33-.41-.79-.7-1.36-.85a4.49 4.49 0 0 0-1.23-.2zM8 12.25a.75.75 0 1 1 0-1.5.75.75 0 0 1 0 1.5z"/>
    </svg>
);





const createNewActivity = (roles, name = 'New Activity') => {
    if (!Array.isArray(roles)) roles = [];

    const allRoleNames = ['Subject Coordinator', ...roles.map(r => r.role)];
    const distributionTable = {};
    allRoleNames.forEach(role => {
        distributionTable[role] = {
            'Preparation / Setup': 0,
            'Delivery / Supervision': 0,
        };
    });

    return {
        id: Date.now(), // Unique key for mapping
        activityName: name,
        maxGroupSize: 25,
        weeklyClassTime: 2,
        numberOfGroups: 5,
        distributionTable,
    };
};


const ActivityAllocationTab = ({ term, onAllocationChange }) => {
    const { staffRoles } = useContext(StaffRolesContext);
    const [activities, setActivities] = useState([]);
    const [activeActivityId, setActiveActivityId] = useState(null);

    // Safely initialize activities once staff roles are available from context
    useEffect(() => {
        if (Array.isArray(staffRoles) && activities.length === 0) {
            const initialActivities = [
                createNewActivity(staffRoles, 'Tutorial'),
                createNewActivity(staffRoles, 'Practical'),
                createNewActivity(staffRoles, 'Lab'),
            ];
            setActivities(initialActivities);
            setActiveActivityId(initialActivities[0].id);
        }
    }, [staffRoles]);

    // Perform calculations and notify parent whenever activities change
    useEffect(() => {
        const termMultiplier = term === 'Autumn' ? 1.0 : 0.923;
        const total = activities.reduce((acc, activity) => {
            const allocation = (Number(activity.numberOfGroups) || 0) * (Number(activity.weeklyClassTime) || 0) * termMultiplier * 0.0125;
            return acc + allocation;
        }, 0);
        onAllocationChange(total);
    }, [activities, term, onAllocationChange]);

    const handleUpdateActivity = (id, field, value) => {
        setActivities(activities.map(act => act.id === id ? { ...act, [field]: value } : act));
    };

    const handleDistributionChange = (id, role, task, value) => {
        setActivities(activities.map(act => {
            if (act.id !== id) return act;
            const newDistributionTable = { ...act.distributionTable };
            newDistributionTable[role] = { ...newDistributionTable[role], [task]: parseFloat(value) / 100 || 0 };
            return { ...act, distributionTable: newDistributionTable };
        }));
    };

    const handleAddActivity = () => {
        const newActivity = createNewActivity(staffRoles);
        setActivities([...activities, newActivity]);
        setActiveActivityId(newActivity.id);
    };

    const activeActivity = activities.find(act => act.id === activeActivityId);
    if (!activeActivity) return <div>Loading...</div>; // Render loading state until ready

    const termMultiplier = term === 'Autumn' ? 1.0 : 0.923;
    const activeAllocation = (Number(activeActivity.numberOfGroups) || 0) * (Number(activeActivity.weeklyClassTime) || 0) * termMultiplier * 0.0125;
    const allRoleNames = ['Subject Coordinator', ...(staffRoles || []).map(r => r.role)];

    return (
        <div style={{ ...styles.panel, marginTop: '2rem' }}>
             <div style={styles.tabsHeader}>
                <div style={styles.tabContainer}>
                    {activities.map(act => (
                        <button 
                            key={act.id} 
                            style={activeActivity.id === act.id ? styles.tabButtonActive : styles.tabButton}
                            onClick={() => setActiveActivityId(act.id)}
                        >
                            {`Activity ${activities.indexOf(act) + 1} ${act.activityName}`}
                        </button>
                    ))}
                </div>
                <button style={styles.addButton} onClick={handleAddActivity}>+ Add</button>
            </div>

            <div style={styles.contentArea}>
                <div style={styles.inputGrid}>
                    <InputField label="Tutorial Allocation" value={`${(activeAllocation * 100).toFixed(1)}%`} disabled />
                    <InputField label="Number of groups" type="number" value={activeActivity.numberOfGroups} onChange={e => handleUpdateActivity(activeActivity.id, 'numberOfGroups', e.target.value)} />
                    <InputField label="Max group size per curriculum approval documents" type="number" value={activeActivity.maxGroupSize} onChange={e => handleUpdateActivity(activeActivity.id, 'maxGroupSize', e.target.value)} />
                    <InputField label="Weekly class time per group over 12 weeks in hours" type="number" value={activeActivity.weeklyClassTime} onChange={e => handleUpdateActivity(activeActivity.id, 'weeklyClassTime', e.target.value)} />
                </div>

                <hr style={styles.hr} />

                <h3 style={styles.subHeader}>Allocation per weekly hour per group</h3>
                <table style={styles.table}>
                    <thead>
                        <tr>
                            <th style={styles.th}>Actions</th>
                            <th style={styles.th}>Staff Role</th>
                            <th style={styles.th}>Preparation / Setup</th>
                            <th style={styles.th}>Delivery / Supervision</th>
                        </tr>
                    </thead>
                    <tbody>
                        {allRoleNames.map(role => (
                            <tr key={role}>
                                <td style={styles.td}><span style={{cursor: 'pointer'}}>✏️</span></td>
                                <td style={styles.td}>{role}</td>
                                <td style={styles.td}>
                                    <input type="number" style={styles.tableInput} value={(activeActivity.distributionTable[role]['Preparation / Setup'] * 100).toFixed(0)} onChange={e => handleDistributionChange(activeActivity.id, role, 'Preparation / Setup', e.target.value)} /> %
                                </td>
                                <td style={styles.td}>
                                    <input type="number" style={styles.tableInput} value={(activeActivity.distributionTable[role]['Delivery / Supervision'] * 100).toFixed(0)} onChange={e => handleDistributionChange(activeActivity.id, role, 'Delivery / Supervision', e.target.value)} /> %
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
                 <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: '2rem' }}>
                    <button style={styles.saveButton}>Save</button>
                </div>
            </div>
        </div>
    );
};

const InputField = ({ label, ...props }) => (
    <div>
        <label style={styles.label}>{label}</label>
        <input style={styles.input} {...props} />
    </div>
);


